examples.code:
- name: ¿Existe la config?
  ansible.builtin.stat: { path: /etc/app/app.conf }
  register: conf
- name: Generar config por defecto
  ansible.builtin.template: { src: app.conf.j2, dest: /etc/app/app.conf }
  when: not conf.stat.exists

APP_PORT={{ app_port }}
DEBUG={{ 'true' if entorno != 'prod' else 'false' }}
{% for k, v in extra_env.items() %}
{{ k }}={{ v }}
{% endfor %}
